// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;
contract LTFToken {
//---------- 元数据----------
string public name = "LTFToken";
string public symbol = "LTF202430552557";
uint8 public decimals = 18;
uint256 public totalSupply;
//---------- 权限----------
address public owner;
modifier onlyOwner() {
require(msg.sender == owner, "LTFToken: caller is not the owner");
_;
}
//---------- 状态----------
// 这两个 mapping 就是"账本"。代币不存在于任何钱包里，只存在于这里。
mapping(address => uint256) private _balances;
mapping(address => mapping(address => uint256)) private _allowances;
//---------- 事件----------
event Transfer(address indexed from, address indexed to, uint256 value);
event Approval(address indexed owner, address indexed spender, uint256 value);
constructor() {
owner = msg.sender;
}
//---------- 只读查询----------
function balanceOf(address account) public view returns (uint256) {
return _balances[account];
}
function allowance(address _owner, address spender) public view returns (uint256) {
return _allowances[_owner][spender];
}
//---------- TODO 1：转账----------
// 要求：to 不能是零地址；msg.sender 余额必须足够；
//扣msg.sender、加 to；发出 Transfer 事件；返回 true。
function transfer(address to, uint256 value) public returns (bool) {
    // 1. 检查输入
    require(to != address(0), "LTFToken: transfer to the zero address");
    // 2. 检查状态
    require(_balances[msg.sender] >= value, "LTFToken: insufficient balance");
    // 3. 改状态
    _balances[msg.sender] -= value;
    _balances[to] += value;
    // 4. 发事件
    emit Transfer(msg.sender, to, value);
    // 5. 返回
    return true;
}
//---------- TODO 2：授权----------
// 要求：记录msg.sender 允许 spender 花 value；发出 Approval 事件；返回 true。
function approve(address spender, uint256 value) public returns (bool) {
    _allowances[msg.sender][spender] = value;
    emit Approval(msg.sender, spender, value);
    return true;
}
//---------- TODO 3：代扣转账----------
// 要求：from 的余额必须足够；msg.sender 在 from 处的额度必须足够；
//额度减value；扣 from、加 to；发出 Transfer 事件；返回 true。
function transferFrom(address from, address to, uint256 value) public returns (bool) {
    require(to != address(0), "LTFToken: transferFrom to the zero address");
    require(_allowances[from][msg.sender] >= value, "LTFToken: insufficient allowance");
    require(_balances[from] >= value, "LTFToken: insufficient balance");

    _allowances[from][msg.sender] -= value;
    _balances[from] -= value;
    _balances[to] += value;

    emit Transfer(from, to, value);
    return true;
}
//---------- TODO 4：增发（只有 owner 能调）----------
// 要求：to 不能是零地址；totalSupply 加 value；to 余额加 value；
//发出Transfer 事件，from 填 address(0)。
function mint(address to, uint256 value) public onlyOwner {
    require(to != address(0), "LTFToken: mint to the zero address");
    totalSupply += value;
    _balances[to] += value;
    emit Transfer(address(0), to, value);
}
//---------- TODO 5：销毁自己的代币----------
// 要求：msg.sender 余额必须足够；余额减 value；totalSupply 减 value；
//发出Transfer 事件，to 填 address(0)。
function burn(uint256 value) public {
    require(_balances[msg.sender] >= value, "LTFToken: burn amount exceeds balance");
    _balances[msg.sender] -= value;
    totalSupply -= value;
    emit Transfer(msg.sender, address(0), value);
}
}
